<template>
  <v-container fluid grid-list-lg class="site-page site-page--wide home-page">
    <v-layout align-center row wrap>
      <v-flex md7 xs12>
        <section class="hero-copy">
          <h1 class="site-identity-title">{{ model.profile.name }}</h1>
          <h2 class="site-identity-summary">{{ model.profile.homeHeadline }}</h2>
          <p class="site-lead">{{ model.profile.homeSummary }}</p>
          <p class="site-meta hero-location">{{ model.profile.locationSummary }}</p>
          <div class="site-actions site-actions--stack-mobile hero-actions">
            <v-btn :to="{path: constants.solutionsPath}"
                   class="site-action site-action--primary"
                   color="primary">
              <v-icon left>work_outline</v-icon>
              {{ titles.solutionsPage }}
            </v-btn>
            <v-btn :to="{path: constants.contactPath}"
                   class="site-action site-action--secondary"
                   color="primary"
                   outline>
              <v-icon left>mail</v-icon>
              {{ titles.homeContactAction }}
            </v-btn>
          </div>
        </section>
      </v-flex>
      <v-flex md5 xs12>
        <v-card class="site-card site-card--interactive site-card--edge-media profile-card" flat>
          <CSImage :alt="model.profile.profileImageAlts[0]"
                   :cover="true"
                   :eager="true"
                   :height="$vuetify.breakpoint.xsOnly ? '280px' : '360px'"
                   :src="model.profile.profileImages[0]"
                   @click.native="imageViewer.showFullScreenImage(0)"
                   position="center"
                   v-ripple
                   width="100%"/>
          <CSImageViewer :imageAlts="model.profile.profileImageAlts"
                         :imageCaptions="profileImageCaptions"
                         :images="model.profile.profileImages" ref="imageViewer"/>
        </v-card>
      </v-flex>
    </v-layout>
  </v-container>
</template>

<style lang="stylus" scoped>
.home-page
  align-items center

.hero-location
  margin 14px 0 0

.hero-actions
  margin-top 22px

.profile-card
  overflow hidden
</style>

<script lang="ts">
import {Component} from 'vue-property-decorator'
import CSImage from '@/cs/view/CSImage.vue'
import CSImageViewer from '@/cs/view/CSImageViewer.vue'
import {CSImageViewerType} from '@/cs/vuetify/CSVuetifyTypes'
import PortalPageBase from '@/view/PortalPageBase'
import {absoluteAssetUrl, canonicalUrl, descriptionFrom, organizationReference, organizationStub, pageMetaInfo, personId, personReference, socialCardPath, stripHtml, websiteId} from '@/model/Seo'
import {Locale} from '@/model/content/Locale'

@Component({components: {CSImage, CSImageViewer}})
export default class Introduction extends PortalPageBase {
  pageTitle = this.titles.homePage

  get imageViewer() {
    return this.reference<CSImageViewerType>('imageViewer')
  }

  get profileImageCaptions() {
    return this.model.profile.profileImages.map(() => this.titles.profilePicture)
  }

  metaInfo(): any {
    const profile = this.model.profile
    const introductionUrl = canonicalUrl(this.constants.introductionPath)
    const contactLink = (prefix: string) => profile.contactLinks.find(link => link.url.startsWith(prefix))
    const email = contactLink('mailto:')?.url.replace('mailto:', '')
    const telephone = contactLink('tel:')?.url.replace('tel:', '')
    const structuredData = {
      '@context': 'https://schema.org',
      '@graph': [
        {
          '@type': 'Person',
          '@id': personId(),
          name: stripHtml(profile.name),
          jobTitle: stripHtml(profile.title),
          url: introductionUrl,
          image: absoluteAssetUrl(profile.profileImages[0]),
          sameAs: profile.professionalLinks.map(link => link.url),
          email,
          telephone,
          description: descriptionFrom(profile.homeSummary),
          nationality: {'@type': 'Country', name: 'Slovakia'},
          address: {'@type': 'PostalAddress', addressCountry: 'SK'},
          knowsLanguage: ['en', 'sk'],
          knowsAbout: [
            'Software architecture',
            'Native Android development',
            'Native iOS development',
            'C++ systems',
            'SDK design',
            'AWS',
            'Full-stack TypeScript',
            'Product management',
            'Technical project leadership',
            'AI-agent workflows'
          ],
          alumniOf: profile.education.map(entry => ({'@type': 'CollegeOrUniversity', name: entry.school})),
          worksFor: organizationReference()
        },
        organizationStub(),
        {
          '@type': 'ProfessionalService',
          '@id': `${introductionUrl}#service`,
          name: `${stripHtml(profile.name)} ${this.titles.homeServiceName}`,
          serviceType: this.titles.homeServiceName,
          url: introductionUrl,
          description: this.titles.homeDescription,
          provider: organizationReference(),
          areaServed: this.titles.homeAreaServed
        },
        {
          '@type': 'ProfilePage',
          '@id': `${introductionUrl}#page`,
          isPartOf: {'@id': websiteId()},
          mainEntity: personReference(),
          inLanguage: Locale.active,
          name: this.titles.homeWebsiteName
        }
      ]
    }
    return pageMetaInfo(
      this.titles.homeSeoTitle,
      this.titles.homeDescription,
      this.constants.introductionPath,
      socialCardPath(this.constants.introductionPath),
      structuredData
    )
  }

  beforeRouteEnter(to: any, from: any, next: any) {
    super.beforeRouteEnter(to, from, next)
  }
}
</script>
