    <v-layout class="cs-viewer fill-height"
              role="dialog"
              aria-modal="true"
              :aria-label="labels.imageViewerLabel"
              @touchstart.passive="onTouchStart"
              @touchend.passive="onTouchEnd">
      <div class="cs-viewer__stage">
        <transition :name="routerTransition">
          <CSImage :key="fullscreenImage"
                   v-if="fullscreenImage"
                   :alt="fullscreenImageAlt"
                   :eager="true"
                   :src="fullscreenImage"
                   class="cs-viewer__image" height="100%" width="100%"/>
        </transition>
      </div>

      <v-btn class="cs-viewer__btn cs-viewer__btn--close" dark fab flat
             :aria-label="labels.closeImageViewerLabel" :title="labels.closeImageViewerLabel"
             @click="hideFullScreenImage()">
        <v-icon>close</v-icon>
      </v-btn>
      <v-btn class="cs-viewer__btn cs-viewer__btn--prev" dark fab flat
             :aria-label="labels.previousImageLabel" :title="labels.previousImageLabel" v-if="isPreviousButtonVisible"
             @click.stop="showPreviousFullScreenImage()">
        <v-icon>chevron_left</v-icon>
      </v-btn>
      <v-btn class="cs-viewer__btn cs-viewer__btn--next" dark fab flat
             :aria-label="labels.nextImageLabel" :title="labels.nextImageLabel" v-if="isNextButtonVisible"
             @click.stop="showNextFullScreenImage()">
        <v-icon>chevron_right</v-icon>
      </v-btn>

      <div class="cs-viewer__meta" :class="{'has-caption': fullscreenImageCaption}"
           aria-live="polite" v-if="fullscreenImage">
        <span class="cs-viewer__caption" v-if="fullscreenImageCaption">{{ fullscreenImageCaption }}</span>
        <span class="cs-viewer__counter">{{ imageCounter }}</span>
      </div>
    </v-layout>
  </v-dialog>
</template>

