<script lang="ts">
  import { Component, Prop, Watch } from 'vue-property-decorator'
  import { CSVue } from '@/cs/CSVue'
  import CSImage from '@/cs/view/CSImage.vue'
  import { CSImageViewerType } from '@/cs/vuetify/CSVuetifyTypes'
  import { activeUi } from '@/model/content/active'

  @Component({ components: { CSImage } })
  export default class CSImageViewer extends CSVue implements CSImageViewerType {
    labels = activeUi()
    @Prop({ required: true }) images!: string[]
    @Prop({ default: () => [] }) imageAlts!: string[]
    @Prop({ default: () => [] }) imageCaptions!: string[]
    @Prop({ default: true }) showCaption!: boolean
    routerTransition = 'viewer-open'
    fullscreenImage: string = ''
    isFullScreenImageDialogVisible = false
    imageIndex = 0
    isNextButtonVisible = true
    isPreviousButtonVisible = true
    closeCleanupTimer: number | null = null
    touchStartX = 0
    touchStartY = 0
    touchStartTime = 0

    updateButtonsVisibility() {
      this.isNextButtonVisible = this.imageIndex < this.images.lastIndex()
      this.isPreviousButtonVisible = this.imageIndex > 0
    }

    get fullscreenImageAlt() { return this.imageAlts[this.imageIndex] || '' }
    get fullscreenImageCaption() { return this.showCaption ? this.imageCaptions[this.imageIndex] || '' : '' }
    get imageCounter() { return `${this.imageIndex + 1} / ${this.images.length}` }

    showFullScreenImage(index: number) {
      this.routerTransition = 'viewer-open'
      this.imageIndex = index
      this.updateButtonsVisibility()
      this.fullscreenImage = this.images[index]
      this.isFullScreenImageDialogVisible = true
    }

    hideFullScreenImage() {
      this.isFullScreenImageDialogVisible = false
    }

    // Delays image cleanup until Vuetify's dialog leave transition has completed.
    @Watch('isFullScreenImageDialogVisible')
    onDialogVisibilityChanged(visible: boolean) {
      if (visible) {
        if (this.closeCleanupTimer !== null) window.clearTimeout(this.closeCleanupTimer)
        this.closeCleanupTimer = null
        window.addEventListener('keydown', this.onKeyDown)
      } else {
        window.removeEventListener('keydown', this.onKeyDown)
        this.closeCleanupTimer = window.setTimeout(() => {
          this.fullscreenImage = ''
          this.closeCleanupTimer = null
        }, 300)
      }
    }

    onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'ArrowRight' && this.isNextButtonVisible) {
        event.preventDefault()
        this.showNextFullScreenImage()
      } else if (event.key === 'ArrowLeft' && this.isPreviousButtonVisible) {
        event.preventDefault()
        this.showPreviousFullScreenImage()
      }
    }

    onTouchStart(event: TouchEvent) {
      if (event.touches.length !== 1) return
      this.touchStartX = event.touches[0].clientX
      this.touchStartY = event.touches[0].clientY
      this.touchStartTime = Date.now()
    }

    onTouchEnd(event: TouchEvent) {
      if (!event.changedTouches.length || !this.touchStartTime) return
      const touch = event.changedTouches[0]
      const deltaX = touch.clientX - this.touchStartX
      const deltaY = touch.clientY - this.touchStartY
      const elapsed = Date.now() - this.touchStartTime
      this.touchStartTime = 0

      if (elapsed > 800 || Math.abs(deltaX) < 56 || Math.abs(deltaX) < Math.abs(deltaY) * 1.25) return
      if (deltaX < 0 && this.isNextButtonVisible) this.showNextFullScreenImage()
      else if (deltaX > 0 && this.isPreviousButtonVisible) this.showPreviousFullScreenImage()
    }

    beforeDestroy() {
      window.removeEventListener('keydown', this.onKeyDown)
      if (this.closeCleanupTimer !== null) window.clearTimeout(this.closeCleanupTimer)
    }

    showNextFullScreenImage() {
      this.routerTransition = 'slide-left'
      this.imageIndex++
      this.updateButtonsVisibility()
      this.fullscreenImage = this.images[this.imageIndex]
    }

    showPreviousFullScreenImage() {
      this.routerTransition = 'slide-right'
      this.imageIndex--
      this.updateButtonsVisibility()
      this.fullscreenImage = this.images[this.imageIndex]
    }
  }
</script>
